#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn timestamp_offsets_and_nanos() {
        let z = parse_timestamp("2026-01-02T03:04:05.5Z").unwrap();
        assert_eq!(parse_timestamp("2026-01-02T05:04:05.5+02:00").unwrap(), z);
        assert_eq!(parse_timestamp("2026-01-02T01:04:05.5-02:00").unwrap(), z);
        assert_eq!(
            parse_timestamp("1000000000").unwrap(),
            UNIX_EPOCH + Duration::from_secs(1)
        );
        assert!(parse_timestamp("yesterday").is_err());
        assert!(parse_timestamp("2026-01-02T05:04:05+xx:00").is_err());
        assert!(parse_timestamp("2026-01-02T05:04:05+02:yy").is_err());
        assert_eq!(
            format_timestamp(UNIX_EPOCH - Duration::from_secs(5)),
            "1970-01-01T00:00:00.000000000Z"
        );
    }
}
